WFJ.Data.add("book", {
  ["a46dfdd3ed0797a7"] = { "Caro diario,\n\noggi il mio acerrimo nemico, ⟦Narain Soothfancy=Narain Veravite⟧, ha cercato di ingannarmi mandando dei tirapiedi a prendere il suo posto all'esecuzione. La SUA esecuzione. Ci credi?\n\nMi ero dato tanta pena per architettare questo piano diabolico e stanarlo da quella dannata capanna, e lui mi fa questo? Pazienza... Sono troppo arrabbiato per continuare a scrivere. Torno più tardi.", "." },
  ["a4936a6785d9aa2f"] = { "Molti ⟦Highborne=Alti Nobili⟧, però, sopravvissero indenni al cataclisma. Raggiunsero le coste della nuova terra insieme agli altri elfi della notte. Benché Malfurion diffidasse delle intenzioni degli ⟦Highborne=Alti Nobili⟧, era certo che senza le energie del Pozzo non avrebbero potuto causare veri danni.", "." },
  ["a4acf239ab8fffef"] = { "Eppure una tribù, nota come gli Arathi, capì che i troll stavano diventando una minaccia troppo grande per essere ignorata. Gli Arathi volevano riunire tutte le tribù sotto il proprio dominio, così da poter opporre un fronte unito alle bande da guerra dei troll.", "." },
  ["a4ad2f52a3ae1e9d"] = { "degli anni, il Tidebearer svaniva. A ogni flusso e riflusso delle maree, il Tidebearer era sempre meno se stesso: perdeva la sua forma corporea, appariva e scompariva a intermittenza, finché, negli ultimi giorni della sua vita, si recò sulla spiaggia dove aveva trovato la Pietra, entrò in mare e scomparve per l'ultima volta.\n\nGenerazioni dopo, la ⟦Stone of the Tides=Pietra delle Maree⟧ fu portata dalle onde sulle rive di Rovotorto, e fu scelto un altro Tidebearer, quando il troll portò la Pietra a", "." },
  ["a4c374239e9a8530"] = { "Ferren Marcus\n\nAbate supremo del ⟦Scarlet Monastery=Monastero Scarlatto⟧\n\nCittadino di Stratholme\n\nCaduto in difesa del ⟦Scarlet Monastery=Monastero Scarlatto⟧ durante il Primo Assalto di Summertide", "." },
  ["a4d91cae266588ae"] = { "Padre e figlio combatterono con fervore per contenere la marea crescente dello sciame di insettoidi a ⟦Silithus=Silitus⟧. Dalla fortezza di ⟦Ahn'Qiraj=Ahn'qiraj⟧, un flusso apparentemente infinito di silitidi continuava a rinforzare le file delle forze Qiraji invasori. L'intera ⟦Silithus=Silitus⟧ era sotto assedio.", "." },
  ["a4dc830696270816"] = { "Khardros e i suoi guerrieri Granmartello si diressero a nord attraverso le porte di sbarramento di Dun Algaz e fondarono un loro regno nella lontana vetta di Grim Batol. Lì i Granmartello prosperarono e ricostituirono le loro riserve di tesori. Thaurissan e i suoi Ferroscuro non ebbero la stessa fortuna. Umiliati e furenti per la sconfitta, giurarono vendetta contro ⟦Ironforge=Forgiardente⟧. Guidando il suo popolo molto più a sud, Thaurissan fondò una città (a cui diede il proprio nome) nelle splendide ⟦Redridge Mountains=Montagne Crestarossa⟧.", "." },
})
